    const label=t=>range==='24H'?new Date(t).toISOString().slice(11,16):new Date(t).toISOString().slice(5,10);
    const axis=Array.from({length:5},(_,i)=>`<span>${label(periodStart()+periodLength()*i/4)}</span>`).join('');
